class Solution {
public:
    int minStoneSum(vector<int>& piles, int k) {
        int V = 0;
        for (int x : piles) if (x > V) V = x;
        vector<int> freq(V + 1, 0);
        for (int x : piles) freq[x]++;
        int p = V;
        for (int i = 0; i < k; i++) {
            while (p > 1 && freq[p] == 0) p--;
            if (p <= 1) break;
            freq[p]--;
            freq[(p + 1) / 2]++;
        }
        long long total = 0;
        for (int v = 1; v <= V; v++) total += (long long)v * freq[v];
        return (int)total;
    }
};
